def f(g, mode='h'):
    h=len(g); w=len(g[0])
    fullr=[i for i in range(h) if len(set(g[i]))==1]
    fulld=[j for j in range(w) if len({g[i][j] for i in range(h)})==1]
    def bands(seq,n):
        b=[]; prev=-1
        for x in seq+[n]:
            if x-prev>1: b.append((prev+1,x)); prev=x
        return b
    rb=bands(fullr,h); cb=bands(fulld,w)
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    for r0,r1 in rb:
        for c0,c1 in cb:
            cnt={}
            for i in range(r0,r1):
                for j in range(c0,c1):
                    cnt[g[i][j]]=cnt.get(g[i][j],0)+1
            bg=max(cnt,key=cnt.get)
            accs={c for c in cnt if c!=bg}
            if len(accs)!=1: continue
            acc=next(iter(accs))
            # detect if accent touches both vertical edges or both horizontal edges of region
            hv=(any(g[r0+dr][c0]==acc for dr in range(r1-r0-r0 if False else [1,0])-[-1,0] ) )
            # simpler: check edges
            touch_hv = (any(g[r][c0]==acc for r in range(r0,r1)) and any(g[r][c1-1]==acc for r in range(r0,r1)))
            touch_ht = (any(g[r0][c]==acc for c in range(c0,c1)) and any(g[r1-1][c]==acc for c in range(c0,c1)))
            if mode=='h' and touch_hv or mode=='v' and touch_ht:
                for i in range(r0,r1):
                    for j in range(c0,c1): out[i][j]=acc
            elif mode=='h' and touch_ht or mode=='v' and touch_hv:
                for i in range(r0,r1):
                    for j in range(c0,c1): out[i][j]=acc
            else:
                for i in range(r0,r1):
                    for j in range(c0,c1):
                        if g[i][j]==acc: out[i][j]=bg
