def comps_of(g,r0,r1,c0,c1,acc):
    seen=set(); out=[]
    for a in range(r0,r1):
        for b in range(c0,c1):
            if g[a][b]==acc and (a,b) not in seen:
                q=deque([(a,b)]); seen.add((a,b)); comp=[]
                while q:
                    aa,bb=q.popleft(); comp.append((aa,bb))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=aa+da,bb+db
                        if r0<=na<r1 and c0<=nb<c1 and g[na][nb]==acc and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                out.append(comp)
    return out
def info(g):
    h=len(g); w=len(g[0])
    fullr=[i for i in range(h) if len(set(g[i]))==1]
    fulld=[j for j in range(w) if len({g[i][j] for i in range(h)})==1]
    def bands(seq,n):
        b=[]; prev=-1
        for x in seq+[n]:
            if x-prev>1: b.append((prev+1,x)); prev=x
        return b
    rb=bands(fullr,h); cb=bands(fulld,w)
    res=[]
    for r0,r1 in rb:
        for c0,c1 in cb:
            cnt={}
            for i in range(r0,r1):
                for j in range(c0,c1):
                    cnt[g[i][j]]=cnt.get(g[i][j],0)+1
            bg=max(cnt,key=cnt.get)
            accs={c for c in cnt if c!=bg}
            if len(accs)==1:
                acc=next(iter(accs))
                cs=comps_of(g,r0,r1,c0,c1,acc)
                # bbox of each comp
                for comp in cs:
                    rows=[p[0] for p in comp]; cols=[p[1] for p in comp]
                    res.append(dict(r0=r0,r1=r1,c0=c0,c1=c1, comp=(min(rows),max(rows),min(cols),max(cols)), size=len(comp), bbox_area=(max(rows)-min(rows)+1)*(max(cols)-min(cols)+1)))
    return res
