def f(g):
    h,w=len(g),len(g[0])
    fullr=[i for i in range(h) if len(set(g[i]))==1]
    fulld=[j for j in range(w) if all(g[i][j]==g[0][j] for i in range(h))]
    def bands(seq,n):
        b=[]; prev=-1
        for x in seq+[n]:
            if x-prev>1: b.append((prev+1,x)); prev=x
        return b
    rb=bands(fullr,h); cb=bands(fulld,w)
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    cands=[]
    for r0,r1 in rb:
        for c0,c1 in cb:
            cnt={}
            for i in range(r0,r1):
                for j in range(c0,c1): cnt[g[i][j]]=cnt.get(g[i][j],0)+1
            bg=max(cnt,key=lambda v:cnt[v])
            accs={c for c in cnt if c!=bg}
            if len(accs)!=1: continue
            acc=next(iter(accs))
            cands.append((cnt[acc],(r0,r1,c0,c1),acc,bg,(r1-r0)*(c1-c0)))
    cmax=max(c[0] for c in cands)
    for n,(r0,r1,c0,c1),a,b,_ in cands:
        if n==cmax:
            for i in range(r0,r1):
